script:
// Crop Cycle — consolidated automation (replaces the 4 legacy scripts).
// Authoritative logic lives in the server controller (crop_cycle.py); this
// script provides live feedback, keeps the auto-managed grids read-only and
// gives instant errors for bad bed ranges before save.

frappe.ui.form.on('Crop Cycle', {
    refresh(frm) {
        // Varieties Grown & Individual Beds are filled by the server on save.
        ['varieties_grown', 'individual_beds'].forEach(function (f) {
            frm.set_df_property(f, 'cannot_add_rows', true);
            frm.set_df_property(f, 'cannot_delete_rows', true);
        });

        // Bed action buttons — each fills the relevant log row and saves,
        // which lets the server update the Individual Beds & rollups.
        if (!frm.is_new()) {
            const grp = __('Bed Actions');
            frm.add_custom_button(__('Replant Bed(s)'), () => replant_beds(frm), grp);
            frm.add_custom_button(__('Uproot Bed(s)'), () => uproot_beds(frm), grp);
            frm.add_custom_button(__('Clear Bed(s)'), () => clear_beds(frm), grp);
        }
    },

    validate(frm) {
        // Bed numbers are unique per greenhouse; From/To must be well-formed.
        // Overlaps are only warned about (legacy data), never blocked.
        const seen = {};
        const overlaps = [];
        (frm.doc.bed_range || []).forEach(function (r) {
            if (!r.from_bed || !r.to_bed) {
                frappe.throw(__('Greenhouse crop cycle row {0}: From Bed and To Bed are required.', [r.idx]));
            }
            if (r.from_bed > r.to_bed) {
                frappe.throw(__('Greenhouse crop cycle row {0}: From Bed ({1}) cannot be greater than To Bed ({2}).',
                    [r.idx, r.from_bed, r.to_bed]));
            }
            for (let b = r.from_bed; b <= r.to_bed; b++) {
                if (seen[b]) {
                    overlaps.push(__('Bed {0} appears in rows {1} and {2}', [b, seen[b], r.idx]));
                } else {
                    seen[b] = r.idx;
                }
            }
        });
        if (overlaps.length) {
            frappe.msgprint({
                title: __('Check bed ranges'),
                indicator: 'orange',
                message: __('Overlapping beds detected (a bed should belong to only one range):') +
                    '<br>' + overlaps.slice(0, 10).join('<br>'),
            });
        }
    },
});

// Live per-row area on the Greenhouse crop cycle (Bed Range) grid.
function recalc_bed_area(frm, cdt, cdn) {
    const r = locals[cdt][cdn];
    if (r.from_bed && r.to_bed && r.bed_length && r.bed_width) {
        const n = Math.max(0, r.to_bed - r.from_bed + 1);
        frappe.model.set_value(cdt, cdn, 'total_beds_area', n * r.bed_length * r.bed_width);
    }
}

frappe.ui.form.on('Bed Range', {
    from_bed: recalc_bed_area,
    to_bed: recalc_bed_area,
    bed_length: recalc_bed_area,
    bed_width: recalc_bed_area,
});

// -- Bed action dialogs ------------------------------------------------------
function _valid_range(v) {
    if (v.from_bed > v.to_bed) {
        frappe.msgprint(__('From Bed cannot be greater than To Bed.'));
        return false;
    }
    return true;
}

function replant_beds(frm) {
    frappe.prompt(
        [
            { fieldname: 'from_bed', label: __('From Bed'), fieldtype: 'Int', reqd: 1 },
            { fieldname: 'to_bed', label: __('To Bed'), fieldtype: 'Int', reqd: 1 },
            { fieldname: 'new_variety', label: __('New Variety'), fieldtype: 'Link', options: 'Item', reqd: 1 },
            { fieldname: 'qty_replanted', label: __('Qty Replanted'), fieldtype: 'Int' },
            { fieldname: 'seedling_source', label: __('Seedling Source'), fieldtype: 'Select', options: '\nPurchased from Breeder\nIn-house Propagation' },
            { fieldname: 'replant_date', label: __('Date'), fieldtype: 'Date', default: frappe.datetime.get_today(), reqd: 1 },
        ],
        (v) => {
            if (!_valid_range(v)) return;
            frm.add_child('replanting_logs', {
                replant_date: v.replant_date, from_bed: v.from_bed, to_bed: v.to_bed,
                new_variety: v.new_variety, qty_replanted: v.qty_replanted, seedling_source: v.seedling_source,
            });
            frm.save().then(() => frappe.show_alert(
                { message: __('Replanted beds {0}–{1} with {2}', [v.from_bed, v.to_bed, v.new_variety]), indicator: 'green' }));
        },
        __('Replant Bed(s)'), __('Replant')
    );
}

function uproot_beds(frm) {
    frappe.prompt(
        [
            { fieldname: 'from_bed', label: __('From Bed'), fieldtype: 'Int', reqd: 1 },
            { fieldname: 'to_bed', label: __('To Bed'), fieldtype: 'Int', reqd: 1 },
            { fieldname: 'reason', label: __('Reason'), fieldtype: 'Select', reqd: 1, options: '\nLow Yield\nDisease\nVariety Change\nAge (End of Life)\nStorm Damage\nOther' },
            { fieldname: 'qty_uprooted', label: __('Qty Uprooted'), fieldtype: 'Int' },
            { fieldname: 'uproot_date', label: __('Date'), fieldtype: 'Date', default: frappe.datetime.get_today(), reqd: 1 },
        ],
        (v) => {
            if (!_valid_range(v)) return;
            frm.add_child('uprooting_logs', {
                uproot_date: v.uproot_date, from_bed: v.from_bed, to_bed: v.to_bed,
                reason: v.reason, qty_uprooted: v.qty_uprooted,
            });
            frm.save().then(() => frappe.show_alert(
                { message: __('Uprooted beds {0}–{1}', [v.from_bed, v.to_bed]), indicator: 'orange' }));
        },
        __('Uproot Bed(s)'), __('Uproot')
    );
}

function clear_beds(frm) {
    frappe.prompt(
        [
            { fieldname: 'from_bed', label: __('From Bed'), fieldtype: 'Int', reqd: 1 },
            { fieldname: 'to_bed', label: __('To Bed'), fieldtype: 'Int', reqd: 1 },
        ],
        (v) => {
            if (!_valid_range(v)) return;
            let n = 0;
            (frm.doc.individual_beds || []).forEach((b) => {
                if (b.bed_number >= v.from_bed && b.bed_number <= v.to_bed) {
                    b.status = 'Empty';
                    b.variety = null;
                    b.plant_count = 0;
                    n += 1;
                }
            });
            if (!n) {
                frappe.msgprint(__('No individual beds found in that range. Save the bed ranges first.'));
                return;
            }
            frm.refresh_field('individual_beds');
            frm.dirty();
            frm.save().then(() => frappe.show_alert(
                { message: __('Cleared {0} bed(s)', [n]), indicator: 'blue' }));
        },
        __('Clear Bed(s)'), __('Clear')
    );
}
